import csv
import io
import re


def parse_csv(raw_csv: str):
    width = 2
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    ))

    if not records:
        return {"columns": [], "rows": []}

    def normalize(record):
        if len(record) > width:
            return record[:width - 1] + [",".join(record[width - 1:])]
        return record + [""] * (width - len(record))

    header_index = next(
        (i for i, record in enumerate(records)
         if len(record) == width and any(cell.strip() for cell in record)),
        None,
    )
    if header_index is None:
        header_index = next(
            (i for i, record in enumerate(records)
             if any(cell.strip() for cell in record)),
            None,
        )
    if header_index is None:
        return {
            "columns": ["column_1", "column_2"],
            "rows": [normalize(record) for record in records],
        }

    columns = normalize(records[header_index])
    data_start = header_index + 1

    # A header-count estimate alone does not justify consuming data records.
    # Recognize a stacked header when a sparse top row is followed by field labels.
    if len(records[header_index]) == width and data_start < len(records):
        lower = records[data_start]
        if (
            any(not cell.strip() for cell in columns)
            and len(lower) == width
            and all(cell.strip() for cell in lower)
            and re.search(r"(?:^|[\W_])(?:id|identifier|code|key)$",
                          lower[0].strip(), re.IGNORECASE)
            and not re.search(r"(?:^|[\W_])(?:id|identifier|code|key)$",
                              columns[0].strip(), re.IGNORECASE)
        ):
            columns = [
                " ".join(cell for cell in (top, bottom) if cell.strip())
                for top, bottom in zip(columns, lower)
            ]
            data_start += 1

    return {
        "columns": columns,
        "rows": [normalize(record) for record in records[data_start:]],
    }
